function currentSet(){return state.ai&&Array.isArray(state.ai.looks)&&state.ai.looks.length?state.ai:null;}
function currentOutfit(){const set=currentSet();if(!set)return null;return set.looks[validPick(state.pick,set)?state.pick:0];}
function validPick(n,set){return Number.isInteger(n)&&n>=0&&set&&n<set.looks.length;}
function pieceRow(p){
 const ref=p.refId?resaleRefs.find(r=>r.id===p.refId):null;
 return `<li class="piece-row">${ref?`<img src="${esc(ref.image)}" alt="">`:''}<div><strong>${esc(p.name)}</strong>${p.detail?` <span class="detail">${esc(p.detail)}</span>`:''}${ref?`<span class="kind resale">DPP-verified resale</span><a href="${esc(ref.href)}">${esc(ref.buy)} · View listing ↗</a>`:'<span class="kind new">Styling suggestion</span>'}</div></li>`;
}
function lookCard(look,i){
 return `<section class="look-card" id="lookCard${i}"><header><span class="look-num">${i+1}</span><h3>${esc(look.title)}</h3></header><p class="muted">${esc(look.summary)}</p><ul class="piece-list">${look.pieces.map(pieceRow).join('')}</ul><div class="ai-actions"><button type="button" class="solid-button" data-save-index="${i}">Save look ${i+1}</button></div></section>`;
}
function persist(){const {photo,...rest}=state;try{localStorage.setItem(key,JSON.stringify(rest));}catch{toast('This browser cannot save. Changes may be lost when you leave.');}}
function savePhoto(data){try{if(data)localStorage.setItem(photoKey,data);else localStorage.removeItem(photoKey);return true;}catch{toast('The photo is too large for this browser to store.');return false;}}
function measureLine(){const b=state.body;const parts=[];if(b.height)parts.push(`Height ${b.height} cm`);if(b.weight)parts.push(`Weight ${b.weight} kg`);if(b.bust||b.waist||b.hip)parts.push(`Bust / waist / hip ${[b.bust,b.waist,b.hip].map(v=>v||'—').join(' / ')}`);return parts.join(' · ');}
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2800);}
function syncAvatar(){
 const img=$('avatarArt');
 const own=ownPhoto();
 const femalePoses=['assets/avatar-female.png?v=pair','assets/avatar-female-side.png?v=orig','assets/avatar-female-back.png?v=orig'];
 const malePoses=['assets/avatar-male.png?v=orig','assets/avatar-male-side.png?v=orig','assets/avatar-male-back.png?v=orig'];
 const src=own?state.photo:(state.avatar===0?femalePoses[state.pose]:malePoses[state.pose]);
 img.style.transform='';
 if(img.getAttribute('src')!==src)img.src=src;
 img.alt=own?'Uploaded photo':`${state.avatar===0?'Woman':'Man'} avatar, ${poses[state.pose].toLowerCase()}, wearing the TECH SHELL JACKET`;
 $('poseChoices').hidden=own;$('poseDivider').hidden=own;
 document.querySelectorAll('[data-pose]').forEach(btn=>{const on=Number(btn.dataset.pose)===state.pose;btn.classList.toggle('selected',on);btn.setAttribute('aria-pressed',String(on));});
 document.querySelectorAll('[data-look]').forEach(btn=>{const on=Number(btn.dataset.look)===state.look;btn.classList.toggle('selected',on);btn.setAttribute('aria-pressed',String(on));const thumb=btn.querySelector('img');const s=art(state.avatar,Number(btn.dataset.look),0);if(thumb&&thumb.getAttribute('src')!==s)thumb.src=s;});
 const line=measureLine();const chip=$('measureChip');chip.hidden=!line;chip.textContent=line;
}
function render(){
 const face=ownPhoto()?state.photo:(state.avatar===0?'assets/avatar-face-female.png?v=orig':'assets/avatar-face-male.png?v=orig');$('profileFace').src=face;$('profileFace').classList.toggle('own-face',ownPhoto());
 const set=currentSet();const outfit=currentOutfit();
 if($('savedCount'))$('savedCount').textContent=`${state.saved.length} saved`;
 const gen=$('generateBtn');if(gen){gen.disabled=aiBusy;gen.innerHTML=aiBusy?'<span class="spinner" aria-hidden="true"></span>Generating':'Generate';}
 $('styleGender').innerHTML=[['Woman',0],['Man',1]].map(([label,i])=>`<button type="button" data-style-gender="${i}" class="theme-chip ${i===state.avatar?'selected':''}" aria-pressed="${i===state.avatar}">${label}</button>`).join('');
 $('themeChoices').innerHTML=themes.map((t,i)=>`<button type="button" data-theme="${i}" class="theme-chip ${i===state.theme?'selected':''}" aria-pressed="${i===state.theme}">${t}</button>`).join('');
 $('outfitThumbs').innerHTML=aiBusy?`<div class="gen-loading" role="status"><span class="spinner" aria-hidden="true"></span><span>Generating</span></div>`:(set?set.looks.map((l,i)=>{const on=i===(validPick(state.pick,set)?state.pick:0);return `<button type="button" data-pick="${i}" class="outfit-option look-thumb ${on?'selected':''}" aria-pressed="${on}" aria-label="Look ${i+1} ${esc(l.title)}">${l.image?`<img src="${esc(l.image)}" alt="">`:`<span class="swatch">${esc(l.title)}</span>`}<span>${i+1}</span></button>`;}).join(''):'');
 const mine=state.photo?`<button data-avatar="mine" class="quick-avatar ${ownPhoto()?'selected':''}" aria-pressed="${ownPhoto()}" aria-label="My photo"><img class="own-face" src="${state.photo}" alt=""></button>`:'';$('avatarQuickChoices').innerHTML=people.map((p,i)=>`<button data-avatar="${i}" class="quick-avatar ${!ownPhoto()&&i===state.avatar?'selected':''}" aria-pressed="${!ownPhoto()&&i===state.avatar}" aria-label="${p}"><img src="${i===0?'assets/avatar-face-female.png?v=orig':'assets/avatar-face-male.png?v=orig'}" alt=""></button>`).join('')+mine;
 $('poseChoices').innerHTML=poses.map((p,i)=>`<button type="button" data-pose="${i}" class="pose-option ${i===state.pose?'selected':''}" aria-pressed="${i===state.pose}">${p}</button>`).join('');
 $('avatarChoices').innerHTML=people.map((p,i)=>`<button data-avatar="${i}" class="quick-avatar ${i===state.avatar?'selected':''}" aria-pressed="${i===state.avatar}"><img src="${i===0?'assets/avatar-female.png?v=pair':'assets/avatar-male.png?v=orig'}" alt=""><span>${p}</span></button>`).join('');
 syncAvatar();
}
function saveLook(title,index){const set=currentSet();if(!set){toast('Generate a look first, then save it.');return;}const i=validPick(index,set)?index:(validPick(state.pick,set)?state.pick:0);const look=set.looks[i];const text=String(title||look.title).trim().slice(0,36);if(!text){toast('Give this look a name first.');return;}state.saved.unshift({title:text,look:look.title,theme:set.theme,query:set.query||state.query,avatar:people[state.avatar],avatarId:state.avatar,image:look.image||'',pieces:look.pieces.map(p=>p.name).join(' · '),ai:{...set,looks:[look]}});state.saved=state.saved.slice(0,15);persist();render();toast(`Saved “${look.title}” to your lookbook`);}
const headings={passport:'PRODUCT PASSPORT / 001',style:'STYLING STUDIO',archive:'DESIGN DETAILS',create:'SAME BRAND',future:'NEXT CHAPTER',about:'ABOUT THIS EXPERIENCE'};
function openFeature(which){
 if(which==='passport'){location.href='passport/index.html';return;}
 if(which==='future'){location.href='resale/index.html';return;}
 let html='';$('featureDialog').classList.remove('style-view');
 if(which==='archive')html=`<h2>Design details.</h2><p class="muted">Four views of this TECH SHELL JACKET.</p><div class="gallery detail-gallery">${[['front.webp','Front'],['side-left.webp','Left'],['side-right.webp','Right'],['back.webp','Back']].map(([file,label])=>`<figure><img src="assets/details/${file}" alt="Jacket ${label}"><figcaption>${label}</figcaption></figure>`).join('')}</div>`;
 if(which==='style'){
  const set=currentSet();
  const owned=`<h3 class="match-head">Owned</h3><div class="match-list"><article class="match-item">${pieceVisual(ownedJacket)}<div><span class="kind own">Owned</span><strong>${ownedJacket.name}</strong><p>${ownedJacket.buy}</p><a href="${ownedJacket.href}">${ownedJacket.hrefLabel} ↗</a></div></article></div>`;
  const head=`<h2>How do you want to wear it today?</h2><p class="muted">Current avatar ${people[state.avatar]}</p>${owned}`;
  if(aiBusy)html=`${head}<div class="gen-loading dialog-loading" role="status"><span class="spinner" aria-hidden="true"></span><p>Generating…</p></div>`;
  else if(state.aiError)html=`${head}<p class="ai-error" role="alert">${esc(state.aiError)}</p><button type="button" class="solid-button" data-regenerate>Try again</button>`;
  else if(set){const i=validPick(state.pick,set)?state.pick:0;const look=set.looks[i];const visual=look.image?`<img src="${esc(look.image)}" alt="Full look: ${esc(look.title)}">`:`<div class="look-placeholder"><span>${esc(set.theme||'')} · Look ${i+1}</span><span>Image coming soon</span></div>`;const nav=set.looks.length>1?`<button type="button" class="text-button" data-pick="${(i+set.looks.length-1)%set.looks.length}">← Previous</button><button type="button" class="text-button" data-pick="${(i+1)%set.looks.length}">Next →</button>`:'';html=`<div class="style-layout"><figure class="look-hero">${visual}</figure><div class="style-side"><h2>${esc(set.theme)} · Look ${i+1} / ${set.looks.length}</h2><p class="muted">Current avatar ${people[state.avatar]}</p>${owned}<h3 class="match-head">AI styling · ${esc(set.theme)}</h3>${lookCard(look,i)}<div class="ai-actions">${nav}<button type="button" class="text-button" data-regenerate>Regenerate for this theme ↻</button></div><p class="fine">Created by ${esc(set.source||'AI stylist')} for “${esc(people[validAvatar(set.avatar)?set.avatar:state.avatar])}” and “${esc(set.theme)}”. Pieces marked DPP-verified resale can be contacted on the resale page.</p></div></div>`;$('featureDialog').classList.add('style-view');}
  else html=`${head}<p class="muted">Pick a theme, then tap Generate.</p><button type="button" class="solid-button" data-regenerate>Generate</button>`;
 }
 if(which==='create')html=`<h2>My lookbook</h2><p class="muted">Keep the wears you like for next time.</p>${state.saved.length?state.saved.map((s,i)=>`<article class="saved-card"><img src="${esc(s.image||'assets/details/front.webp')}" alt="Saved look"><div><h3>${esc(s.title)}</h3><p>${s.theme?`${esc(s.theme)} · `:''}${esc(s.pieces||s.look||'')} · ${esc(people[validAvatar(s.avatarId)?s.avatarId:0])}</p></div><button class="text-button" data-restore="${i}">Wear this ↗</button></article>`).join(''):'<p>Nothing saved yet. Generate a look, then tap Save this look.</p>'}<p class="fine">The last 15 looks stay in this browser.</p>`;
 if(which==='future')html=`<h2>Make the next wear worth looking forward to.</h2><p class="muted">A product identity can travel with a longer wearing life.</p><dl class="record"><div><dt>Restyle</dt><dd>Start from the jacket you own and find new ways to wear it.</dd></div><div><dt>Care file</dt><dd>Later care notes can follow confirmed materials and the wash label.</dd></div><div><dt>People to people</dt><dd>Owners can later share product notes, talk, or start a transfer.</dd></div></dl><button class="solid-button" data-open="style">Back to styling ↗</button><p class="fine">This prototype does not run real trade, ownership transfer, or live care records.</p>`;
 if(which==='about')html=`<h2>One jacket, more ways to wear it.</h2><p>This is an interaction study built around your TECH SHELL JACKET. In the centre you can switch the woman or man preset, or use a photo you upload. The windows lead to product notes, styling, design details, same-brand pieces, and an AI that only answers from this item’s digital product passport.</p><p>The jacket film is from your upload. Styling images are photographic previews and may differ from the original piece.</p><p class="fine">Open digital passport goes to the full Digital Product Passport site, with details on their own pages. Ask AI cites those records with source links, and says when something is not on file. Photos, measurements, and saved looks stay in this browser.</p>`;
 if(!html)return;$('dialogMeta').textContent=headings[which];$('featureContent').innerHTML=html;if(!$('featureDialog').open)$('featureDialog').showModal();
}
document.addEventListener('click',e=>{
 const open=e.target.closest('[data-open]');if(open)openFeature(open.dataset.open);
 const choice=e.target.closest('[data-look]');if(choice){state.look=Number(choice.dataset.look);$('styleFeedback').textContent='';persist();render();}
 const avatar=e.target.closest('[data-avatar]');if(avatar){if(avatar.dataset.avatar==='mine')state.usePhoto=true;else{state.usePhoto=false;state.avatar=Number(avatar.dataset.avatar);}persist();render();}
 const pose=e.target.closest('[data-pose]');if(pose){state.pose=Number(pose.dataset.pose);persist();render();}
 const saveIdx=e.target.closest('[data-save-index]');if(saveIdx)saveLook(undefined,Number(saveIdx.dataset.saveIndex));
 const theme=e.target.closest('[data-theme]');if(theme){state.theme=Number(theme.dataset.theme);state.ai=null;state.pick=0;state.aiError='';persist();render();if($('featureDialog').open)openFeature('style');}
 const styleGender=e.target.closest('[data-style-gender]');if(styleGender){state.usePhoto=false;state.avatar=Number(styleGender.dataset.styleGender);state.ai=null;state.pick=0;state.aiError='';persist();render();if($('featureDialog').open)openFeature('style');}
 const pick=e.target.closest('[data-pick]');if(pick){const inDialog=!!pick.closest('#featureDialog');state.pick=Number(pick.dataset.pick);persist();render();openFeature('style');const card=$(`lookCard${state.pick}`);if(card&&inDialog)card.scrollIntoView({block:'start'});else $('featureContent').scrollTop=0;}
 if(e.target.closest('[data-regenerate]'))generateOutfit();
 const saved=e.target.closest('[data-restore]');if(saved){const entry=state.saved[Number(saved.dataset.restore)];if(entry){state.usePhoto=false;if(validAvatar(entry.avatarId))state.avatar=entry.avatarId;if(typeof entry.query==='string')state.query=entry.query.slice(0,80);if(entry.ai&&Array.isArray(entry.ai.looks))state.ai=entry.ai;state.pick=0;const ti=themes.indexOf(entry.theme);if(ti>=0)state.theme=ti;state.aiError='';persist();render();$('featureDialog').close();toast('This look is back on');}}
});
$('styleForm').addEventListener('submit',e=>{e.preventDefault();$('styleFeedback').textContent='';generateOutfit();});


$('saveLookBtn').onclick=()=>saveLook();
let pendingPhoto;
function showPreview(src){const preview=$('photoPreview');preview.hidden=!src;preview.src=src||'';$('clearPhoto').hidden=!src;}
function editAvatar(){pendingPhoto=undefined;for(const m of measures)$(m.id).value=state.body[m.key]||'';showPreview(state.photo);$('avatarDialog').showModal();}
function readPhoto(file){return new Promise((resolve,reject)=>{const img=new Image();const url=URL.createObjectURL(file);img.onload=()=>{const max=900;const scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',0.82));};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('read'));};img.src=url;});}
$('profileBtn').onclick=editAvatar;$('editAvatarBtn').onclick=editAvatar;
$('photoInput').addEventListener('change',async()=>{const file=$('photoInput').files&&$('photoInput').files[0];$('photoInput').value='';if(!file)return;if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type)){toast('Please upload a JPG, PNG, WEBP, or GIF.');return;}if(file.size>12*1024*1024){toast('Please keep the image under 12 MB.');return;}try{pendingPhoto=await readPhoto(file);showPreview(pendingPhoto);}catch{toast('This image could not be read.');}});
$('clearPhoto').onclick=()=>{pendingPhoto=null;showPreview('');};
$('confirmAvatar').onclick=()=>{const body={};for(const m of measures){const text=$(m.id).value.trim();if(!text){body[m.key]='';continue;}const n=Number(text);if(!Number.isFinite(n)||n<m.min||n>m.max){toast(`${m.label} should be ${m.min}–${m.max} ${m.unit}.`);$(m.id).focus();return;}body[m.key]=String(Math.round(n*10)/10);}if(pendingPhoto===null){if(!savePhoto(''))return;state.photo='';state.usePhoto=false;}else if(typeof pendingPhoto==='string'){if(!savePhoto(pendingPhoto))return;state.photo=pendingPhoto;state.usePhoto=true;}state.body=body;pendingPhoto=undefined;persist();render();$('avatarDialog').close();toast('Avatar saved');};
$('closeAvatar').onclick=()=>$('avatarDialog').close();$('closeFeature').onclick=()=>$('featureDialog').close();
for(const id of ['featureDialog','avatarDialog'])$(id).addEventListener('click',e=>{if(e.target===$(id))$(id).close();});
const video=$('jacketVideo');$('videoToggle').onclick=()=>{if(video.paused)video.play().catch(()=>toast('Tap the video to play again'));else video.pause();};
function videoLabel(){$('videoToggle').textContent=video.paused?'▶':'Ⅱ';$('videoToggle').setAttribute('aria-label',video.paused?'Play item video':'Pause item video');}
video.addEventListener('play',videoLabel);video.addEventListener('pause',videoLabel);
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)video.pause();
for(let a=0;a<people.length;a++)for(let l=0;l<looks.length;l++)for(let p=0;p<poses.length;p++){const im=new Image();im.src=art(a,l,p);}
render();
(function initAsk(){
 const thread=$('askThread');const chips=$('askChips');const form=$('askForm');const input=$('askInput');const send=$('askSend');
 if(!thread||!chips||!form||!input)return;
 const reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 const src=(label,href)=>({label,href});
 const topics=[
  {id:'care',show:true,label:'Care',chip:'How do I wash this jacket?',keys:['how do i wash','how to wash','wash','clean','care','laundry','dryer','tumble','iron','bleach','softener','清洗','洗涤','护理','怎么洗','怎么清洗'],answer:'Gentle machine wash, low heat.\nTumble dry on permanent press, low.\nNo bleach, dry-cleaning, or fabric softener.',sources:[src('Care Guide','passport/care.html')]},
  {id:'material',show:true,label:'Materials',chip:'What is special about its materials?',keys:['what is special','material','fabric','hemp','silk','nylon','composition','材质','面料','材料','特点'],answer:'Woven shell: 84% nylon / 16% spandex, wind- and water-resistant.\nKnit panels: hemp outside, silk inside, for breathability.',sources:[src('Product Info','passport/basic-info.html')]},
  {id:'resale',show:true,label:'Resale records',chip:'If I resell later, what records can I share?',keys:['if i resell','resale','resell','transfer','records','passport','ownership','转售','记录','护照','转让'],answer:'Share this DPP as one file: authenticity, ownership, materials, care, and sustainability.\nThe jacket is already marked verified.',sources:[src('Authentication','passport/authentication.html'),src('Care Guide','passport/care.html'),src('Sustainability','passport/sustainability.html')]},
  {id:'auth',label:'Authenticity',chip:'Is this jacket authentic?',keys:['authentic','verified','fake','real','genuine','真伪','正品','认证'],answer:'Verified authentic. Product ID TJ2024001.\nOriginal purchaser, 0 transfers.',sources:[src('Authentication','passport/authentication.html')]},
  {id:'origin',label:'Origin',chip:'Where was it made?',keys:['where','origin','made','china','italy','usa','trace','supply','产地','哪里','供应链','追溯'],answer:'Made in China.\nHemp yarn from the USA, silk yarn from Italy.',sources:[src('Product Info','passport/basic-info.html'),src('Traceability','passport/traceability.html')]},
  {id:'carbon',label:'Footprint',chip:'What is the carbon footprint?',keys:['carbon','co2','footprint','water','sustain','gots','pfas','recycled','碳','足迹','可持续','环保'],answer:'30 kg CO2e · 2,200 L water.\nMain woven and knit listed as 100% recycled.',sources:[src('Sustainability','passport/sustainability.html')]},
  {id:'weather',label:'Weather',chip:'Can I wear it in the rain?',keys:['rain','waterproof','wind','weather','outdoor','雨','防水','防风'],answer:'Listed as waterproof, windproof, and breathable.\nNo storm rating is on file, so I cannot confirm more than that.',sources:[src('Product Info','passport/basic-info.html')]},
  {id:'price',label:'Price & weight',chip:'How much does it weigh, and what did it cost?',keys:['price','cost','weight','585','400','多重','价格','多少钱'],answer:'$400 · 585 g.\nColours: Black, Sage Green. Sizes XS–XL.',sources:[src('Product Info','passport/basic-info.html')]}
 ];
 const unknown={answer:'That is not in this jacket’s digital product passport, so I cannot confirm it.',sources:[]};
 const unknownHints=['shrink','return','refund','warranty','lifespan','how long will','who designed','designer','fit me','size am i','缩水','退货','保修','设计师'];
 let busy=false;
 function addMsg(role,who){
  const el=document.createElement('article');
  el.className='ask-msg '+role;
  el.innerHTML=`<span class="ask-who">${who}</span><p class="ask-body"></p>`;
  thread.appendChild(el);
  thread.scrollTop=thread.scrollHeight;
  return el.querySelector('.ask-body');
 }
 function addSources(body,sources){
  if(!sources.length)return;
  const box=document.createElement('p');
  box.className='ask-sources';
  sources.forEach(s=>{
   const a=document.createElement('a');
   a.href=s.href;a.target='_blank';a.rel='noopener';a.textContent=s.label;
   box.appendChild(a);
  });
  body.parentElement.appendChild(box);
 }
 async function typeText(el,text){
  if(reduce){el.textContent=text;return;}
  el.textContent='';
  const parts=text.split(/(\s+)/);
  for(const part of parts){
   el.textContent+=part;
   thread.scrollTop=thread.scrollHeight;
   await sleep(part.trim()?16+Math.random()*22:8);
  }
 }
 function score(q,topic){
  const t=q.toLowerCase();
  let n=0;
  for(const k of topic.keys)if(t.includes(k))n+=k.length>4?2:1;
  if(topic.chip&&t===topic.chip.toLowerCase())n+=20;
  return n;
 }
 function matchTopic(q){
  const t=q.toLowerCase();
  if(unknownHints.some(h=>t.includes(h)))return null;
  let best=null,bestScore=0;
  for(const topic of topics){
   const n=score(q,topic);
   if(n>bestScore){best=topic;bestScore=n;}
  }
  return bestScore>=1?best:null;
 }
 async function ask(raw){
  const q=String(raw||'').trim();
  if(!q||busy)return;
  busy=true;send.disabled=true;input.value='';
  thread.hidden=false;thread.classList.add('open');
  addMsg('user','You').textContent=q;
  const body=addMsg('ai','Passport AI');
  const dots=document.createElement('span');
  dots.className='ask-typing';dots.innerHTML='<i></i><i></i><i></i>';
  dots.setAttribute('aria-label','Thinking');
  body.appendChild(dots);
  await sleep(reduce?80:420+Math.random()*380);
  const topic=matchTopic(q);
  const pack=topic||unknown;
  body.textContent='';
  await typeText(body,pack.answer);
  addSources(body,pack.sources);
  thread.scrollTop=thread.scrollHeight;
  busy=false;send.disabled=false;input.focus();
 }
 chips.innerHTML=topics.map(t=>`<button type="button" class="ask-card" data-ask="${esc(t.chip)}"><small>${esc(t.label)}</small><strong>${esc(t.chip)}</strong></button>`).join('');
 chips.addEventListener('click',e=>{const btn=e.target.closest('[data-ask]');if(btn)ask(btn.dataset.ask);});
 form.addEventListener('submit',e=>{e.preventDefault();ask(input.value);});
})();
if(document.modelContext?.registerTool){try{
 document.modelContext.registerTool({name:'configure_virtual_avatar',description:'Set the local avatar, pose, preset look, and measurements',inputSchema:{type:'object',properties:{avatar:{type:'integer',minimum:0,maximum:1},look:{type:'integer',minimum:0,maximum:2},pose:{type:'integer',minimum:0,maximum:2},name:{type:'string',maxLength:24},bust:{type:'number'},waist:{type:'number'},hip:{type:'number'},height:{type:'number'},weight:{type:'number'}}},execute:async args=>{if(validAvatar(args.avatar)){state.avatar=args.avatar;state.usePhoto=false;}if(validLook(args.look))state.look=args.look;if(validPose(args.pose))state.pose=args.pose;if(typeof args.name==='string')state.name=args.name.slice(0,24);const next={...state.body};for(const m of measures){if(typeof args[m.key]==='number'){const n=args[m.key];if(n>=m.min&&n<=m.max)next[m.key]=String(Math.round(n*10)/10);}}state.body=next;persist();render();return{content:[{type:'text',text:'Avatar updated'}]};}});
 document.modelContext.registerTool({name:'open_experience',description:'Open an atelier experience window',inputSchema:{type:'object',properties:{door:{type:'string',enum:['style','archive','create','future']}},required:['door']},execute:async args=>{openFeature(args.door);return{content:[{type:'text',text:'Window opened'}]};}});
 document.modelContext.registerTool({name:'save_current_outfit',description:'Save the current look to the local lookbook',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:36}},required:['title']},execute:async args=>{saveLook(args.title);return{content:[{type:'text',text:'Look saved'}]};}});
}catch{}}
